mapper.select:
select n.notify_id, n.user_id, n.survey_id, n.answer_id, n.title, n.content, n.read_flag, n.create_time,
       s.survey_name
from biz_survey_notify n
left join biz_survey s on s.survey_id = n.survey_id

    and n.user_id = #{userId}
    and n.read_flag = #{readFlag}
    and n.survey_id = #{surveyId}

order by n.notify_id desc
